-- GET 101: Engineer in Society (old code EGR 101)
-- =============================================================================
-- 139 questions: 104 from the supplied GET 101 quiz (checked and re-ordered so the
-- correct answer is not always option A; 11 items dropped as opinion, unverifiable or
-- institution-specific) plus 35 new questions on the course outcomes: science vs engineering vs
-- technology, the engineering family, professional bodies, code of ethics, SDGs,
-- safety and risk, competency skills. The course content was taken from the
-- supplied course outline and notes.
-- ASSUMPTIONS (please confirm): 100 Level, first semester, 1 unit, Faculty of Engineering.
-- ADDS ONLY: joins an existing GET 101 paper if there is one; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('Engineering is best described as:', '["The art of practical application of scientific knowledge in the design, building and control of facilities for the convenience of humans","The pure study of natural phenomena without application","A trade that requires no scientific knowledge","A branch of art history"]'::jsonb, 0, 'Engineering applies scientific knowledge practically to design and build useful systems for human convenience.', 'Overview of Engineering as a Profession'),
  ('Compared to technology programs, engineering undergraduate programs generally include:', '["Less mathematics","More mathematics and higher-level mathematics","No mathematics at all","The exact same mathematics content"]'::jsonb, 1, 'Engineering programs emphasize more advanced mathematics than technology programs.', 'Overview of Engineering as a Profession'),
  ('Engineering undergraduate programs often focus on:', '["Application only","Neither theory nor application","Theory, while technology programs focus on application","Marketing skills"]'::jsonb, 2, 'Engineering = theory-focused; technology = application-focused.', 'Overview of Engineering as a Profession'),
  ('Upon graduation, engineering graduates typically spend their time:', '["Making plans work","Selling products","Avoiding design tasks","Planning, while technology graduates make plans work"]'::jsonb, 3, 'Engineers plan; engineering technologists implement and make plans work.', 'Overview of Engineering as a Profession'),
  ('Graduates from engineering technology programs are typically referred to as:', '["Technologists","Engineers","Scientists","Apprentices"]'::jsonb, 0, 'Technology program graduates are often called technologists.', 'Overview of Engineering as a Profession'),
  ('Professional engineering licensure is generally available to:', '["Anyone regardless of education","Only graduates of engineering programs, not technology programs","Only technology program graduates","Only those with a trade certificate"]'::jsonb, 1, 'Licensure as a registered engineer is typically restricted to engineering program graduates.', 'Overview of Engineering as a Profession'),
  ('Before the Industrial Revolution, engineering-type work relied mainly on:', '["Computer-aided design","Robotics","Artisans, craftsmen, and apprenticeship/trial-and-error methods","Digital simulation"]'::jsonb, 2, 'Pre-industrial development relied on artisans/craftsmen and apprenticeship-based trial and error.', 'Overview of Engineering as a Profession'),
  ('The 1st Industrial Revolution is most associated with:', '["Digital revolution and automation","Mass production and assembly lines","Internet of Things","Iron and steel production, mechanization, and steam power"]'::jsonb, 3, 'The 1st Revolution featured iron/steel production, mechanization, and steam power.', 'Overview of Engineering as a Profession'),
  ('The 2nd Industrial Revolution introduced:', '["Urbanization, mass production, assembly lines, electricity, and combustion engines","3-D printing","Cyber-physical systems","Apprenticeship-based learning"]'::jsonb, 0, 'The 2nd Revolution brought urbanization, mass production, assembly lines, electricity, and combustion engines.', 'Overview of Engineering as a Profession'),
  ('The 3rd Industrial Revolution is characterized by:', '["Steam power","Digital revolution, microelectronics, PCs, automation, and globalization","Apprenticeships","Cyber-physical systems advancement"]'::jsonb, 1, 'The 3rd Revolution = digital revolution, microelectronics, PCs, automation, globalization.', 'Overview of Engineering as a Profession'),
  ('The 4th Industrial Revolution involves:', '["Trial-and-error apprenticeships","Steam-powered machinery only","Cyber-physical systems, AI, IoT, big data, and blockchain technology","Hand tools only"]'::jsonb, 2, 'The 4th Revolution introduced cyber-physical systems, renewable energy, robotics, AI, IoT, big data, and blockchain.', 'Overview of Engineering as a Profession'),
  ('The 5th Industrial Revolution emphasizes:', '["Only iron and steel production","Pure manual labor","Elimination of all automation","Communication between humans and machines, and advancement in 3-D printing"]'::jsonb, 3, 'The 5th Revolution focuses on human-machine communication in workspaces and 3-D printing advancement.', 'Overview of Engineering as a Profession'),
  ('Which of these is one of the 12 engineering disciplines listed in the workbook?', '["Aerospace Engineering","Culinary Engineering","Fashion Engineering","Literary Engineering"]'::jsonb, 0, 'Aerospace Engineering is among the 12 listed disciplines.', 'Overview of Engineering as a Profession'),
  ('Every society needs the agricultural sector to provide all of the following EXCEPT:', '["Food","Software applications","Shelter","Clothing"]'::jsonb, 1, 'Agriculture provides food, shelter, clothing, and industrial raw materials — not software.', 'Agricultural & Bioresources Engineering'),
  ('Which of these is a common source of farm power?', '["Lunar power","Magnetic levitation","Wind power","Nuclear fusion"]'::jsonb, 2, 'Wind power is listed among common farm power sources, alongside manual, animal, solar, hydro, and electric power.', 'Agricultural & Bioresources Engineering'),
  ('Common methods of irrigation include all of the following EXCEPT:', '["Surface irrigation","Sprinkler irrigation","Drip irrigation","Combustion irrigation"]'::jsonb, 3, 'The four common irrigation methods are surface, subsurface, sprinkler, and drip — not ''combustion''.', 'Agricultural & Bioresources Engineering'),
  ('Processing operations of agricultural products may involve:', '["Cleaning, drying, cooling, and sorting","Only painting","Only packaging in plastic","Only export documentation"]'::jsonb, 0, 'Cleaning, drying, cooling, and sorting are listed processing operations.', 'Agricultural & Bioresources Engineering'),
  ('Farm Structures designed by Agricultural and Bioresources Engineers include:', '["Shopping malls only","Livestock homes and storage houses","Airports","Power plants only"]'::jsonb, 1, 'Farm structures include residential quarters, livestock homes, storage and processing houses, green houses, and equipment storage.', 'Agricultural & Bioresources Engineering'),
  ('A major hindrance to sustainable agricultural mechanization in Nigeria is:', '["Excess government funding","Too much skilled labor","Poverty and inaccessibility of credit","Overabundance of machinery"]'::jsonb, 2, 'Poverty and inaccessible credit are listed hindrances to mechanization in Nigeria.', 'Agricultural & Bioresources Engineering'),
  ('Which of the following is also listed as a hindrance to agricultural mechanization in Nigeria?', '["Excess of maintenance technicians","Overly favorable soil terrain","Too much government consistency","Illiteracy of farmers"]'::jsonb, 3, 'Illiteracy of farmers is listed as one of the hindrances.', 'Agricultural & Bioresources Engineering'),
  ('The role of Agricultural Bioresources Engineering in sustainable agriculture includes:', '["Conservation of natural resources and environmental management/green technology","Increasing pollution","Reducing food production","Eliminating rural development"]'::jsonb, 0, 'Conservation of natural resources and green technology are key roles discussed.', 'Agricultural & Bioresources Engineering'),
  ('Biomedical Engineering can be described as a discipline that:', '["Focuses solely on financial modeling","Applies mathematics and natural science knowledge to develop ways to utilize materials and forces of nature for the benefit of mankind, in medical sciences","Deals only with road construction","Concerns itself with agricultural irrigation"]'::jsonb, 1, 'Biomedical engineering applies engineering knowledge for the benefit of mankind in medical sciences.', 'Biomedical Engineering'),
  ('Which of the following is a personal product of biomedical engineering listed in the workbook?', '["Tractor","Solar panel","Thermometer","Wind turbine"]'::jsonb, 2, 'Thermometer, syringe, bandage, dentures, etc., are biomedical products listed.', 'Biomedical Engineering'),
  ('A sphygmomanometer is a device used for:', '["Measuring distance","Generating electricity","Filtering water","Checking blood pressure"]'::jsonb, 3, 'A sphygmomanometer checks blood pressure.', 'Biomedical Engineering'),
  ('X-ray machines are described in the workbook as technology that:', '["Allows medical professionals to see broken bones, dental cavities, and other things inside the body","Only measures temperature","Are used solely for cooking","Generate electrical power for hospitals"]'::jsonb, 0, 'X-ray machines let professionals see inside the body for diagnosis.', 'Biomedical Engineering'),
  ('Electrocardiographs are machines that can tell doctors:', '["The patient''s blood type only","Whether a patient''s heart is functioning normally or needs treatment","The patient''s height","The hospital''s electricity bill"]'::jsonb, 1, 'ECGs assess heart function for doctors.', 'Biomedical Engineering'),
  ('In biomedical engineering, nanomaterials are used to:', '["Build bridges","Power vehicles","Carry dyes as contrast agents to detect tumors and deliver treatment directly to cancer","Construct dams"]'::jsonb, 2, 'Nanomaterials in biomedicine carry dyes/treatments to target tumors directly.', 'Biomedical Engineering'),
  ('Biomaterials are defined as:', '["Materials used only in building construction","Materials that cannot be inserted into the body","Materials used exclusively for clothing","Any kind of material that interacts with a biological system like the human body, meant to replace or repair organs/tissues"]'::jsonb, 3, 'Biomaterials interact with biological systems to replace/repair organs or tissues.', 'Biomedical Engineering'),
  ('Engineers in ancient times were referred to as "military engineers" because:', '["Their products were implements of war","They all served in the army","They designed only weapons of mass destruction","They worked exclusively for kings"]'::jsonb, 0, 'They were called military engineers because their products were implements of war.', 'Civil Engineering'),
  ('The first person to call himself a "Civil Engineer" was:', '["Isaac Newton","John Smeaton","Thomas Edison","Alexander Graham Bell"]'::jsonb, 1, 'John Smeaton is recorded as the first to call himself a Civil Engineer.', 'Civil Engineering'),
  ('The first school of civil engineering was established in:', '["Nigeria","Japan","France","Canada"]'::jsonb, 2, 'The first civil engineering school was established in France.', 'Civil Engineering'),
  ('While ancient civil engineers relied on rule of thumb and empirical methods, modern civil engineers use:', '["Guesswork and superstition","Only manual labor","Astrology","Design and calculations"]'::jsonb, 3, 'Modern civil engineers use design and calculations rather than rule of thumb.', 'Civil Engineering'),
  ('NSE stands for Nigerian Society of Engineers, formed in:', '["1958","1982","2001","1899"]'::jsonb, 0, 'NSE was formed in 1958.', 'Civil Engineering'),
  ('The civil engineer who built the stepped pyramid of Egypt was:', '["John Smeaton","Imhotep","Thomas Tredgold","Fisher Cassie"]'::jsonb, 1, 'Imhotep is credited with building the stepped pyramid of Egypt.', 'Civil Engineering'),
  ('Which of these is among the famous ancient civil engineering works listed?', '["The Eiffel Tower","The Burj Khalifa","The Great Wall of China","The Channel Tunnel"]'::jsonb, 2, 'The Great Wall of China (built by General Meng T''ien, 200 BC) is among the listed ancient works.', 'Civil Engineering'),
  ('The first two branches of engineering carved out of civil engineering were:', '["Aerospace and biomedical engineering","Mining and petroleum engineering","Software and chemical engineering","Mechanical and electrical engineering"]'::jsonb, 3, 'Mechanical and electrical engineering were the first two branches carved out of civil engineering.', 'Civil Engineering'),
  ('The duty of a civil engineer, compared to an architect, mainly involves:', '["The design, construction, and maintenance of general infrastructure","Only interior decoration","Only landscaping aesthetics","Marketing of buildings"]'::jsonb, 0, 'Civil engineers handle design, construction, and maintenance of infrastructure, while architects focus on planning.', 'Civil Engineering'),
  ('According to Thomas Tredgold, civil engineering is:', '["Only the study of bridges","The art of directing the great sources of power in nature for the uses and convenience of man","A purely theoretical science","A branch of medicine"]'::jsonb, 1, 'Tredgold''s definition: civil engineering directs natural power sources for human use and convenience.', 'Civil Engineering'),
  ('According to Fisher Cassie, a scientist feels accomplished when:', '["He builds a house","He earns a degree","He makes a scientific discovery, while an engineer feels accomplished when the discovery can be applied to affect man''s life","He publishes a poem"]'::jsonb, 2, 'Cassie distinguished scientists (discovery) from engineers (application to life).', 'Civil Engineering'),
  ('Why is it absurd for an engineering student to cheat during examinations?', '["Because cheating is always detected immediately","Because exams don''t matter for engineers","Because it has no consequence on safety","Because engineering products are critical to human existence, and cheating lowers the quality of education and resulting products"]'::jsonb, 3, 'Cheating lowers education quality, which can affect the quality/safety of engineering products.', 'Civil Engineering'),
  ('The first electrical engineer, who designed the versorium, was:', '["William Gilbert","Michael Faraday","Nikola Tesla","Thomas Edison"]'::jsonb, 0, 'William Gilbert was the first electrical engineer and designed the versorium.', 'Electrical Engineering'),
  ('The two workers whose discoveries elevated electricity to a major technological breakthrough were:', '["Albert Einstein and Isaac Newton","Michael Faraday and Joseph Henry","Galileo and Copernicus","Darwin and Mendel"]'::jsonb, 1, 'Michael Faraday and Joseph Henry''s discoveries were pivotal.', 'Electrical Engineering'),
  ('The difference between a motor and a generator is:', '["They are identical devices with different names","A motor only works on AC, a generator only on DC","A motor converts electrical energy into mechanical energy, while a generator converts mechanical energy into electrical energy","A generator requires no moving parts"]'::jsonb, 2, 'Motor: electrical→mechanical; Generator: mechanical→electrical.', 'Electrical Engineering'),
  ('Incandescent lamps are enclosed in vacuum or inert gases to:', '["Make them brighter only","Reduce their cost","Increase their weight","Prevent or delay the filament''s self-destruction"]'::jsonb, 3, 'Vacuum/inert gas prevents or delays material self-destruction of the filament.', 'Electrical Engineering'),
  ('The "war of currents" was a controversy between:', '["Nikola Tesla (Westinghouse) and Thomas Edison (General Electric)","Faraday and Newton","Tesla and Faraday","Edison and Smeaton"]'::jsonb, 0, 'The war of currents was between Tesla/Westinghouse and Edison/General Electric.', 'Electrical Engineering'),
  ('Which form of current won the "war of currents" to become the industry standard?', '["DC (Direct Current)","AC (Alternating Current)","Static current","No current won"]'::jsonb, 1, 'AC current won the war of currents.', 'Electrical Engineering'),
  ('One reason AC was adopted over DC as the industry standard is:', '["DC was more expensive to transmit","AC could not be generated","AC transformers could easily change voltage and current levels","DC motors were simpler"]'::jsonb, 2, 'AC transformers easily change voltage/current levels — a key reason for adoption.', 'Electrical Engineering'),
  ('The first generating plant in Nigeria was installed in Lagos in the year:', '["1958","1982","2001","1898"]'::jsonb, 3, 'The first generating plant in Nigeria was installed in Lagos in 1898.', 'Electrical Engineering'),
  ('The Electricity Corporation of Nigeria (ECN) and Nigeria Dam Authority (NDA) were amalgamated to form:', '["National Electric Power Authority (NEPA)","COREN","NSE","NIBE"]'::jsonb, 0, 'ECN and NDA were amalgamated into NEPA.', 'Electrical Engineering'),
  ('The first department of electrical engineering was established at:', '["Harvard University in 1900","Darmstadt University of Technology in 1882","University of Lagos in 1958","Oxford University in 1850"]'::jsonb, 1, 'Darmstadt University of Technology established the first electrical engineering department in 1882.', 'Electrical Engineering'),
  ('The standard frequency of Nigeria''s power system is:', '["60Hz","100Hz","50Hz","25Hz"]'::jsonb, 2, 'Nigeria''s standard power system frequency is 50Hz.', 'Electrical Engineering'),
  ('The transmission voltage level in Nigeria is:', '["100kV","11kV","500kV","330kV"]'::jsonb, 3, '330kV is the transmission voltage level in Nigeria.', 'Electrical Engineering'),
  ('Continuous-time signals differ from discrete-time signals in that continuous-time signals are:', '["Defined at all instants in time, while discrete-time signals are defined only at sampling instants","Always digital","Always analog and never digital","Undefined at all times"]'::jsonb, 0, 'Continuous-time signals are defined at all instants; discrete-time signals only at sampling instants.', 'Electronic Engineering'),
  ('The function of an analogue-to-digital converter is to:', '["Convert digital signals back to analog only","Quantize/digitize an analog signal into digital form so it can be read and processed by a microcontroller","Amplify analog signals without conversion","Store data permanently"]'::jsonb, 1, 'An ADC quantizes/digitizes analog signals for microcontroller processing.', 'Electronic Engineering'),
  ('The major function of a diode in an electronic circuit is:', '["To store large amounts of energy","To amplify signals only","To allow the flow of current in one direction only","To generate radio waves"]'::jsonb, 2, 'A diode is a two-terminal device allowing current flow in one direction only.', 'Electronic Engineering'),
  ('The major function of a transistor in an electronic circuit is:', '["To rectify AC voltage only","To store mechanical energy","To measure temperature","To switch or amplify electronic signals"]'::jsonb, 3, 'Transistors are used to switch or amplify electronic signals.', 'Electronic Engineering'),
  ('Diodes differ from transistors in that diodes:', '["Allow current flow in one direction only, while transistors amplify electronic signals","Have three terminals while transistors have two","Cannot be used in circuits","Generate their own power"]'::jsonb, 0, 'Diodes (one-directional current) differ from transistors (amplification).', 'Electronic Engineering'),
  ('Boolean logic is a form of algebra where all values are either:', '["Positive or negative numbers","True or False","Fractions or integers","Colors"]'::jsonb, 1, 'Boolean logic deals with values that are either true or false.', 'Electronic Engineering'),
  ('The Boolean gates listed in the workbook include:', '["Only AND and OR","Only NOT gate","AND, OR, NOT, NAND, NOR, EX-OR, EX-NOR","ADD, SUBTRACT, MULTIPLY"]'::jsonb, 2, 'AND, OR, NOT, NAND, NOR, EX-OR, and EX-NOR are the gates listed.', 'Electronic Engineering'),
  ('An AND gate (A·B) gives a high output (1) when:', '["Any input is high","All inputs are low","Only when no inputs are connected","All inputs are high"]'::jsonb, 3, 'An AND gate outputs high (1) only when all inputs are high.', 'Electronic Engineering'),
  ('An OR gate differs from an Exclusive-OR (Ex-OR) gate in that an OR gate gives a high output when:', '["Any input is high, while an Ex-OR gate gives a high output when one input negates the other","All inputs must be low","No inputs are connected","Power is off"]'::jsonb, 0, 'OR gate: high when any input is high. Ex-OR: high when inputs differ.', 'Electronic Engineering'),
  ('Simplifying the Boolean operation A·Ā gives:', '["1","0 (anything ANDed with its own complement equals 0)","A","Ā"]'::jsonb, 1, 'A·Ā = 0, since a value ANDed with its complement is always 0.', 'Electronic Engineering'),
  ('Simplifying the Boolean operation A + 0 gives:', '["0","1","A (anything ORed with 0 equals itself)","Undefined"]'::jsonb, 2, 'A + 0 = A, since anything ORed with 0 equals itself.', 'Electronic Engineering'),
  ('Computer size is a function of the level of integration of ICs because:', '["Computer size has nothing to do with ICs","Larger ICs always mean larger computers regardless of integration","IC integration only affects color displays","Large scale integration comprising hundreds of thousands of components results in a smaller, more compact computer"]'::jsonb, 3, 'Higher integration (more components per chip) generally enables smaller, more compact computers.', 'Electronic Engineering'),
  ('0.05TB is approximately equivalent to:', '["50,000 MB","5 MB","500 GB","5,000 KB"]'::jsonb, 0, '0.05TB ≈ 50,000 MB (0.05 × 10^6 MB).', 'Electronic Engineering'),
  ('Mechanical Engineering basically deals with:', '["Only chemical reactions","Machines and the production of power, concerned with motion and associated forces","Only software development","Only financial analysis"]'::jsonb, 1, 'Mechanical engineering deals with machines, power production, motion, and forces.', 'Mechanical Engineering'),
  ('Which of these is a product of mechanical engineers listed?', '["Bridges only","Power grids only","Helicopters","Vaccines"]'::jsonb, 2, 'Helicopters, trucks, automobiles, trains, and escalators are listed mechanical engineering products.', 'Mechanical Engineering'),
  ('Mechanical engineering students are expected to take courses in areas including:', '["Only literature","Only foreign languages","Only fine arts","Thermodynamics and fluid mechanics"]'::jsonb, 3, 'Thermodynamics, fluid mechanics, statics/dynamics, and materials engineering are core areas.', 'Mechanical Engineering'),
  ('The acronym CAD means:', '["Computer-Aided Design","Central Automated Drafting","Computer Assembly Diagram","Controlled Automation Device"]'::jsonb, 0, 'CAD = Computer-Aided Design.', 'Mechanical Engineering'),
  ('The acronym CAM means:', '["Central Automation Module","Computer-Aided Manufacturing","Computer Algorithm Method","Controlled Assembly Machine"]'::jsonb, 1, 'CAM = Computer-Aided Manufacturing.', 'Mechanical Engineering'),
  ('Elements found in machines designed by mechanical engineers include:', '["Only software code","Only paper documents","Gears, valves, pulleys/belts, and pistons","Only electrical wires"]'::jsonb, 2, 'Gears, valves, pulleys/belts, and pistons are listed machine elements.', 'Mechanical Engineering'),
  ('A recent offshoot of mechanical engineering includes:', '["Only ancient blacksmithing","Only carpentry","Only tailoring","Mechatronics and Nanotechnology"]'::jsonb, 3, 'Biomedical engineering, mechatronics, nanotechnology, and aeroacoustics engineering are recent offshoots.', 'Mechanical Engineering'),
  ('Biomechanical engineering is concerned with:', '["The mechanical aspects of living bodies, including design and operation of biomechanical systems like artificial organs and prostheses","Only the design of buildings","Only software algorithms","Only financial systems"]'::jsonb, 0, 'Biomechanical engineering deals with mechanical aspects of living bodies, e.g., artificial organs.', 'Mechanical Engineering'),
  ('Mechatronics engineering is described as:', '["A purely mechanical discipline with no electronics","An advanced engineering design approach integrating mechanical, electronics, and intelligent computer software engineering for concurrent product design and manufacturing","A field unrelated to manufacturing","A subset of civil engineering only"]'::jsonb, 1, 'Mechatronics integrates mechanical, electronics, and computer software for concurrent design/manufacturing.', 'Mechanical Engineering'),
  ('Nanotechnology is the development of things, generally:', '["Buildings larger than skyscrapers","Only software applications","Materials and devices on the scale of atoms and molecules","Only agricultural tools"]'::jsonb, 2, 'Nanotechnology deals with materials/devices at the scale of atoms and molecules.', 'Mechanical Engineering'),
  ('The acronym CFD means:', '["Central Frequency Distribution","Computer Frame Design","Continuous Force Detection","Computational Fluid Dynamics — fluid flow analysis using numerical methods"]'::jsonb, 3, 'CFD = Computational Fluid Dynamics, used for fluid flow analysis via numerical methods.', 'Mechanical Engineering'),
  ('Aeroacoustics engineering is an aspect of mechanical engineering concerned with:', '["Identification, analysis, and reduction of noise in aircraft","The taste of aircraft food","The color schemes of aircraft","The pricing of airline tickets"]'::jsonb, 0, 'Aeroacoustics deals with noise identification, analysis, and reduction in aircraft.', 'Mechanical Engineering'),
  ('An advanced manufacturing method listed includes:', '["Only hand carving","3-D printing and Artificial Intelligence","Only blacksmithing","Only weaving"]'::jsonb, 1, '3-D printing, CAD, AI, and computer-aided manufacturing are advanced manufacturing methods listed.', 'Mechanical Engineering'),
  ('A traditional area of specialization in mechanical engineering is:', '["Fashion Design","Culinary Arts","Energy and Power","Literature"]'::jsonb, 2, 'Energy and Power is a traditional mechanical engineering specialization, along with Production, Environmental Control, etc.', 'Mechanical Engineering'),
  ('Production Engineering is concerned with:', '["Only farming","Only food preparation","Only legal documentation","The development of machines to mass produce goods at high rates and levels of accuracy"]'::jsonb, 3, 'Production Engineering develops machines for high-rate, accurate mass production.', 'Mechanical Engineering'),
  ('Environment Control as a mechanical engineering specialization concerns:', '["Control of human environment such as draining, irrigation, ventilation, and air conditioning","Stock market regulation","Political campaigns","Sports management"]'::jsonb, 0, 'Environment Control covers draining, irrigation, ventilating, and air conditioning.', 'Mechanical Engineering'),
  ('The mechanical element of a mechatronic system includes:', '["Only software code","The mechanism, mechanical structures, thermo-fluid, and hydraulics, which interact with the environment","Only electrical wiring","Only sensors"]'::jsonb, 1, 'The mechanical element includes mechanisms, structures, thermo-fluids, and hydraulics.', 'Mechatronics Engineering'),
  ('Electrical/electronic elements of a mechatronic system are used to:', '["Only provide decoration","Replace mechanical elements entirely","Connect electro-mechanical sensors and actuators to control interface/computing hardware","Eliminate the need for sensors"]'::jsonb, 2, 'Electrical/electronic elements connect sensors/actuators to control/computing hardware.', 'Mechatronics Engineering'),
  ('Electromechanical elements such as sensors and actuators:', '["Are identical in function","Have no role in mechatronic systems","Only function in vacuum environments","Sensors detect events/changes in the environment, while actuators produce motion by converting energy and signals into the system"]'::jsonb, 3, 'Sensors detect environmental changes; actuators produce motion by converting energy/signals.', 'Mechatronics Engineering'),
  ('The function of a microprocessor in any mechatronic system is to:', '["Perform arithmetic and logic operations according to instructions stored in its memory","Generate heat for the system","Provide structural support","Replace all sensors"]'::jsonb, 0, 'A microprocessor performs arithmetic/logic operations per stored instructions.', 'Mechatronics Engineering'),
  ('The difference between a microprocessor and a microcontroller is that:', '["A microcontroller cannot perform calculations","They are basically the same, except a microcontroller has more storage devices than a microprocessor","A microprocessor is always larger physically","A microcontroller has no memory"]'::jsonb, 1, 'Per the workbook, they are basically the same except a microcontroller has more storage devices.', 'Mechatronics Engineering'),
  ('An example of a mechatronic system commonly found around us is:', '["Hand tools only","Wooden furniture","Photocopiers","Paper documents"]'::jsonb, 2, 'Photocopiers, intelligent washers/dryers, and modern autofocus cameras are listed examples.', 'Mechatronics Engineering'),
  ('A field where training in Mechatronics Engineering can be applied is:', '["Only ancient history","Only literature studies","Only fashion design","Artificial Intelligence"]'::jsonb, 3, 'AI, robotics/automation, design and product development, and IT/sensors/actuators are listed fields.', 'Mechatronics Engineering'),
  ('The full meaning of CNC machine is:', '["Computer Numerical Control","Central Network Connection","Continuous Numeric Calculation","Computerized Notation Center"]'::jsonb, 0, 'CNC = Computer Numerical Control.', 'Mechatronics Engineering'),
  ('An example of a CNC machine and its use, as given, is:', '["Sewing machines, used for stitching","Lathe machines, used for cutting","Printing presses, used for newspapers","Washing machines, used for laundry"]'::jsonb, 1, 'Lathe machines (cutting) and milling machines (making holes) are given as CNC examples.', 'Mechatronics Engineering'),
  ('Compared to purely mechanical machines, CNC machines allow:', '["No automation at all","Only manual operation","One skilled person to operate several machines, while purely mechanical machines require a skilled technician for every machine","Less precision than mechanical machines"]'::jsonb, 2, 'CNC machines allow one skilled person to operate several machines.', 'Mechatronics Engineering'),
  ('The main concern of Metallurgical and Materials Engineers is:', '["Designing software applications only","Marketing finished products only","Managing financial portfolios only","Producing and applying metals, plastics/polymers, ceramics, and all types of materials for useful purposes in everyday life"]'::jsonb, 3, 'They focus on producing/applying metals, polymers, ceramics, and materials for everyday use.', 'Metallurgical and Materials Engineering'),
  ('Materials are important to engineers and society because:', '["It is through materials that engineering products are produced","Materials have no role in engineering","Only software matters in engineering","Materials are only relevant to art"]'::jsonb, 0, 'Materials are fundamental, since engineering products are made through them.', 'Metallurgical and Materials Engineering'),
  ('An Ore is defined as:', '["A type of plastic polymer","A mineral from which a metal can be economically extracted","A finished metal product","A type of ceramic glaze"]'::jsonb, 1, 'An ore is a mineral from which a metal can be economically extracted.', 'Metallurgical and Materials Engineering'),
  ('Metals and their alloys are used in:', '["Only food preparation","Only clothing manufacture","Making machines and building bridges","Only paper production"]'::jsonb, 2, 'Metals/alloys are used in machines, bridges, building structures, vehicles, railways, and agricultural tools.', 'Metallurgical and Materials Engineering'),
  ('Earlier than now, Metallurgical and Materials Engineers studied three classes of materials, namely:', '["Modern, Postmodern, and Futuristic materials","Only synthetic polymers","Only ceramics","Stone Age, Bronze Age, and Iron Age materials"]'::jsonb, 3, 'Stone Age, Bronze Age, and Iron Age are the three classes mentioned.', 'Metallurgical and Materials Engineering'),
  ('An establishment/organization where graduates of Metallurgical and Materials Engineering can work includes:', '["Iron and Steel companies","Fashion design studios only","Culinary institutions only","Music production studios only"]'::jsonb, 0, 'Iron and Steel, Glass and Cement, and Semi-conducting/Electronics companies are examples listed.', 'Metallurgical and Materials Engineering'),
  ('A specialization in Metallurgical and Materials Engineering includes:', '["Culinary Arts","Physical Metallurgy","Theatre Production","Fashion Merchandising"]'::jsonb, 1, 'Physical Metallurgy, Mechanical Metallurgy, Chemical Metallurgy, Ceramic Engineering, and Biomedical Materials are listed specializations.', 'Metallurgical and Materials Engineering'),
  ('The Engineer in the Society is described as:', '["Someone who only manages finances","Someone who only writes reports","A practitioner who invents, designs, analyzes, builds, and tests machines, systems, and materials to fulfil functional objectives while considering practicality, regulation, safety, and cost","Someone unrelated to design or testing"]'::jsonb, 2, 'Engineers invent/design/build/test while balancing practicality, regulation, safety, and cost.', 'Engineering and the Society'),
  ('One reason given for preferring engineering over other courses is that engineering has:', '["No relevance to daily life","Made farming obsolete","Reduced food production globally","Greatly helped agriculture and food production by building facilities that improve quality of crops and animals"]'::jsonb, 3, 'Engineering''s contribution to agriculture/food production is given as a reason to study it.', 'Engineering and the Society'),
  ('Engineers are responsible for the production of electronic products such as:', '["Satellites","Only paper books","Only clothing","Only musical instruments"]'::jsonb, 0, 'Engineering is responsible for products such as satellites, communication systems, etc.', 'Engineering and the Society'),
  ('Buildings, bridges, and roads were all constructed by:', '["Only architects with no engineering input","Engineers","Only unskilled laborers","Only government officials"]'::jsonb, 1, 'Buildings, bridges, and roads are construction works attributed to engineers.', 'Engineering and the Society'),
  ('Communication was made efficient through engineering products such as:', '["Only handwritten letters","Only smoke signals","Satellites","Only town criers"]'::jsonb, 2, 'Satellites are an engineering product that made communication efficient.', 'Engineering and the Society'),
  ('A difficulty faced by Engineers in Nigeria from the government side, as listed, is:', '["Excess of funding","Overregulation of safety standards only","Too many qualified engineers in government roles","Inadequate opportunities"]'::jsonb, 3, 'Inadequate opportunities is listed as a government-related difficulty faced by engineers in Nigeria.', 'Engineering and the Society'),
  ('Science is best described as the study that seeks to:', '["discover and explain natural phenomena","design and build useful structures and machines","manufacture goods in large quantities","repair machines and equipment"]'::jsonb, 0, 'Science asks "why", building knowledge about nature. Engineering uses that knowledge to design and build solutions.', 'Science, Engineering and Technology'),
  ('Engineering differs from pure science mainly because engineering:', '["avoids the use of mathematics","applies scientific knowledge to design and build solutions to practical problems","is concerned only with describing nature","does not need to consider cost or safety"]'::jsonb, 1, 'Scientists discover; engineers apply knowledge within limits of cost, safety, materials and time.', 'Science, Engineering and Technology'),
  ('In the context of science, engineering and technology, "technology" refers to:', '["only computers and software","the study of ancient history","the tools, products, processes and techniques that result from applying knowledge","only the work of scientists in laboratories"]'::jsonb, 2, 'Technology includes the machines, systems and methods that people use to meet needs.', 'Science, Engineering and Technology'),
  ('An invention differs from an innovation in that an innovation:', '["is always a completely new scientific law","never involves a product or a service","is the same as a patent application","puts a new idea or device into practical use that creates value"]'::jsonb, 3, 'An invention is a new idea or device; innovation is its successful introduction and use.', 'Innovation'),
  ('Which member of the engineering family usually holds a university degree in engineering and is registered to practise?', '["the engineer","the craftsman","the technician","the apprentice"]'::jsonb, 0, 'Engineers plan and design and, once registered with the regulating body, are professionally accountable for their work.', 'The Engineering Family'),
  ('The engineering technologist is typically trained to:', '["replace the engineer in all design decisions","apply established engineering knowledge and technology to practical work","work without any formal training","regulate the engineering profession"]'::jsonb, 1, 'Technologists bridge engineers and technicians, concentrating on application and implementation.', 'The Engineering Family'),
  ('Engineering technicians mainly:', '["design large infrastructure projects alone","set national engineering standards","support engineers and technologists by installing, testing, operating and maintaining equipment","teach engineering theory in universities only"]'::jsonb, 2, 'Technicians carry out routine technical tasks such as measuring, testing and maintenance.', 'The Engineering Family'),
  ('A craftsman in the engineering family is a person who:', '["holds a doctorate in engineering","is responsible for approving all designs","does no practical work","has a skilled trade, such as welding, carpentry or fitting, and works with hands-on skill"]'::jsonb, 3, 'Craftsmen (artisans) are skilled tradespeople whose practical work turns designs into reality.', 'The Engineering Family'),
  ('Arranged from the highest to the lowest level of formal training, the engineering family is usually described as:', '["engineer, technologist, technician, craftsman","craftsman, technician, technologist, engineer","technician, engineer, craftsman, technologist","technologist, craftsman, engineer, technician"]'::jsonb, 0, 'Each cadre has its own role, and all of them work together on a project.', 'The Engineering Family'),
  ('COREN stands for:', '["Committee of Registered Engineers of Nigeria","Council for the Regulation of Engineering in Nigeria","Council of Retired Engineers and Navigators","Corporation for Roads and Engineering Networks"]'::jsonb, 1, 'COREN is the statutory body that regulates engineering practice in Nigeria.', 'Professional Bodies'),
  ('Which statement about COREN and the Nigerian Society of Engineers (NSE) is correct?', '["both are student unions","the NSE issues the legal licence to practise, while COREN is a social club","COREN regulates the practice of engineering, while the NSE is the professional society of engineers","they are two names for the same body"]'::jsonb, 2, 'COREN registers and regulates engineers; the NSE is a professional learned society for its members.', 'Professional Bodies'),
  ('A professional engineering body does all of the following EXCEPT:', '["promote the standards of the profession","organise conferences and training","encourage members to follow a code of ethics","manufacture the products designed by its members"]'::jsonb, 3, 'Professional bodies set standards and support members; they are not manufacturers.', 'Professional Bodies'),
  ('The principle that should rank first in an engineer''s code of ethics is:', '["holding paramount the safety, health and welfare of the public","maximising the employer''s profit","finishing projects as fast as possible","protecting the engineer''s reputation at all costs"]'::jsonb, 0, 'Public welfare comes before every other duty in engineering codes of conduct.', 'Engineers'' Code of Conduct and Ethics'),
  ('An engineer who is offered a bribe to approve substandard materials should:', '["accept it if the amount is small","refuse the bribe and report the matter","accept it and use better materials","ignore the offer and approve the materials"]'::jsonb, 1, 'Codes of ethics require engineers to reject bribery in all its forms and to report unethical practice.', 'Engineers'' Code of Conduct and Ethics'),
  ('A conflict of interest arises when:', '["an engineer disagrees with a colleague about a technical detail","a project is completed ahead of time","a personal interest could influence an engineer''s professional judgement","an engineer attends a training course"]'::jsonb, 2, 'Engineers should avoid conflicts of interest, or disclose them in good time when they cannot be avoided.', 'Engineers'' Code of Conduct and Ethics'),
  ('Whistleblowing in engineering means:', '["stopping all work on a project","spreading rumours about a competitor","taking company equipment home","reporting illegal, unsafe or unethical practice to the proper authority"]'::jsonb, 3, 'Engineers have an ethical duty to report practices that endanger the public.', 'Engineers'' Code of Conduct and Ethics'),
  ('An engineer should undertake work only in areas of:', '["his or her competence","the highest-paying contracts","any field, provided a friend can help","the employer''s choosing, regardless of training"]'::jsonb, 0, 'Practising outside one''s competence puts the public and the engineer''s reputation at risk.', 'Engineers'' Code of Conduct and Ethics'),
  ('Continuing professional development (CPD) requires engineers to:', '["stop studying after graduation","keep learning about developments, laws, codes and standards throughout their careers","attend training only before registration","rely on the knowledge acquired in secondary school"]'::jsonb, 1, 'Technology and standards change, so competence must be maintained.', 'Engineers'' Code of Conduct and Ethics'),
  ('Cheating in examinations is considered unethical for an engineering student mainly because:', '["examinations are not important","the lecturer might be annoyed","engineers will be trusted with the safety of the public, so honesty and competence are required","cheating is allowed in group work"]'::jsonb, 2, 'Dishonesty during training builds habits that can later cost lives.', 'Engineers'' Code of Conduct and Ethics'),
  ('The Sustainable Development Goals (SDGs) were adopted by the United Nations in 2015 and number:', '["8","12","25","17"]'::jsonb, 3, 'The 2030 Agenda contains 17 goals.', 'Sustainable Development Goals'),
  ('SDG 6 is concerned with:', '["clean water and sanitation","affordable and clean energy","quality education","climate action"]'::jsonb, 0, 'Water treatment and supply systems are typical engineering contributions to SDG 6.', 'Sustainable Development Goals'),
  ('SDG 7 is concerned with:', '["clean water and sanitation","affordable and clean energy","zero hunger","life below water"]'::jsonb, 1, 'Solar, wind and hydro projects contribute to SDG 7.', 'Sustainable Development Goals'),
  ('SDG 9 links engineering most directly with:', '["no poverty","gender equality","industry, innovation and infrastructure","peace and justice"]'::jsonb, 2, 'Roads, bridges, power and communication networks are infrastructure.', 'Sustainable Development Goals'),
  ('SDG 13 calls for:', '["quality education for all","decent work for all","reduced inequalities","urgent action to combat climate change and its impacts"]'::jsonb, 3, 'Renewable energy and efficient design help reduce emissions.', 'Sustainable Development Goals'),
  ('Sustainable development is best described as development that:', '["meets present needs without compromising the ability of future generations to meet theirs","maximises profit this year only","avoids all new technology","uses only imported resources"]'::jsonb, 0, 'This is the widely quoted definition from the Brundtland report.', 'Sustainable Development Goals'),
  ('A hazard is:', '["the same thing as a risk","a source of potential harm, whereas risk is the chance that the harm will occur and its severity","the probability of success of a project","the cost of safety equipment"]'::jsonb, 1, 'Hazard: something that can cause harm. Risk: likelihood combined with consequence.', 'Safety and Risk'),
  ('Risk is commonly estimated as the product of:', '["cost and time","speed and distance","likelihood and severity of the harm","size and weight"]'::jsonb, 2, 'A high-likelihood, high-severity hazard has the highest risk.', 'Safety and Risk'),
  ('In the hierarchy of hazard controls, which measure is the most effective?', '["wearing protective equipment","putting up warning signs","giving workers training only","eliminating the hazard"]'::jsonb, 3, 'Order of effectiveness: elimination, substitution, engineering controls, administrative controls, then personal protective equipment.', 'Safety and Risk'),
  ('Personal protective equipment (PPE) is regarded as:', '["the last line of defence, used when other controls cannot remove the hazard","the first and best control","a replacement for training","unnecessary on construction sites"]'::jsonb, 0, 'PPE protects the worker but does not remove the hazard.', 'Safety and Risk'),
  ('A safety factor in design is used to:', '["reduce the cost of materials","provide a margin of safety against uncertainty in loads and material strength","increase the speed of construction","avoid all calculations"]'::jsonb, 1, 'Designing with a margin reduces the chance of failure.', 'Safety and Risk'),
  ('Which of these is a soft skill that engineers need?', '["soldering","computer-aided drafting","communication and teamwork","welding"]'::jsonb, 2, 'Soft skills include communication, teamwork, leadership and time management; the others are technical skills.', 'Engineering Competency Skills'),
  ('Which of these is a digital skill useful to an engineer?', '["memorising tables only","typing without a computer","avoiding data analysis","using spreadsheets and simulation software"]'::jsonb, 3, 'Digital skills include data analysis, programming and design software.', 'Engineering Competency Skills'),
  ('The Industrial Revolution that introduced steam power and mechanisation is the:', '["first","second","third","fourth"]'::jsonb, 0, 'The first revolution (late 1700s) was driven by steam, iron and mechanised production.', 'History of Engineering'),
  ('Mass production, assembly lines and widespread electrical power belong to the:', '["first Industrial Revolution","second Industrial Revolution","third Industrial Revolution","fourth Industrial Revolution"]'::jsonb, 1, 'The second revolution ran from the late 1800s to the early 1900s.', 'History of Engineering'),
  ('Imhotep is remembered in engineering history as the designer of:', '["the Great Wall of China","the Suez Canal","the step pyramid at Saqqara","the Eiffel Tower"]'::jsonb, 2, 'Imhotep served the pharaoh Djoser and is regarded as one of the earliest named engineers.', 'History of Engineering')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where subject_name ilike 'GET 101%' and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'get-101-engineer-in-society'),
       coalesce(t.subject_name, 'GET 101: Engineer in Society'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Engineering'),
       coalesce(t.department, 'General Engineering'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'first'),
       coalesce(t.units, 1)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'get-101-engineer-in-society') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'GET 101%' and subject_id not like '%coming-soon'
 group by 1, 2;
